/* C API of the Rust port of `wrappers.c`, generated by rust-anything. */
#ifndef WRAPPERS_RS_H
#define WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t wrap_xa_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_xa_multi(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_xa_alloc(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_xa_iter(uint64_t seed, int64_t n_i, int64_t seed2);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_wrap_xa_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_xa_multi(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_xa_alloc(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_xa_iter(uint64_t seed, int64_t n_i, int64_t seed2);

#endif /* WRAPPERS_RS_H */
